# Créer une carte centrée sur Lyon (approximativement) avec un style différent
m = folium.Map(location=[45.9, 5.4], zoom_start=12, tiles='CartoDB dark_matter')

# Ajouter le GeoJSON à la carte avec un style personnalisé
folium.GeoJson(
    geojson_data, 
    name="Contour de la commune",
    style_function=lambda x: {'fillColor': 'lightblue', 'color': 'blue', 'weight': 2, 'fillOpacity': 0.3}
).add_to(m)

# Ajouter un contrôle des couches
folium.LayerControl().add_to(m)

# Sauvegarder la carte dans un fichier HTML
m.save("map.html")